insert into audio_clips (id, text, voice, channel) values ('0fea7fe676806729', '先輩、山川商事から見積もりの件で連絡がありまして、値引きと納期短縮の両方を求められています。', 'manager_m', 'in_person') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
