insert into audio_clips (id, text, voice, channel) values ('fb6ae93c7ad8eec2', '値引きは一割、納期も一週間早めてほしいとのことです。私としては、一割は飲んで関係を強化したほうがいいと思うのですが。', 'manager_m', 'in_person') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('e130bff5be205da8', '一割はさすがに厳しいよ。五％なら原価的に飲める。納期短縮は生産ラインに空きがあるから対応できそうだし、両方いけるんじゃないか。', 'staff_junior_m', 'in_person') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('3acce30aadb219b9', 'では五％の値引きと納期一週間短縮、両方を提案書に盛り込みますか。', 'manager_m', 'in_person') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('ae90aaf7526953db', 'いや、待って。さっき空きがあると言ったけど、来月分の受注が入ったから、納期短縮まではもう無理だ。値引きを五％にするなら、納期は今まで通りでいこう。', 'staff_junior_m', 'in_person') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
