insert into items (id, bundle_id, item_type, level, seed_cell_id, setting, relation, function, channel, scene_id, speaker_role, listener_role, topic, stem, correct_index, explanation_ja, explanation_en, vocab_notes, documents, dialogue, narration_clip_id, model_p_correct) values ('641b8c655c', 'sougou_choukai_J1_002', 'sougou_choukai', 'J1', 'desk_huddle+junior_to_senior+what_was_decided@J1', 'desk_huddle', 'junior_to_senior', 'what_was_decided', 'in_person', 'scene_office_desk_pair', null, null, '取引先への値引き・納期対応の結論', '山川商事への対応について、結論はどうなりましたか。', 2, '後輩は最初、取引先の求め通り一割の値引きを飲むべきだと述べるが、先輩は「一割はさすがに厳しい」と否定し、五％なら対応できると言う。さらに先輩はいったん「納期短縮も含めて両方いけるんじゃないか」と述べるが、来月分の受注が入ったことに気づき、納期短縮は無理だと撤回する。最終的な結論は、値引きを五％にとどめ、納期は従来どおりとすることで、後輩もそのように先方へ伝えると答えている。途中で出た「一割」や「両方いける」という発言をそのまま答えにすると誤りになる。', 'The junior''s suggestion of a 10% discount is rejected, and the senior''s early idea of doing both a discount and a shorter delivery is withdrawn once a conflicting order comes in; the final decision is a 5% discount with the delivery date unchanged.', '[{"term": "納期", "reading": "のうき", "meaning": "delivery date/deadline"}, {"term": "受注", "reading": "じゅちゅう", "meaning": "receiving an order"}, {"term": "原価", "reading": "げんか", "meaning": "cost price"}]', '[]', '[{"speaker_role": "後輩", "text": "先輩、山川商事から見積もりの件で連絡がありまして、値引きと納期短縮の両方を求められています。", "clip_id": "0fea7fe676806729"}, {"speaker_role": "先輩", "text": "どのくらい求められているの。", "clip_id": "592d77a770a45b0f"}, {"speaker_role": "後輩", "text": "値引きは一割、納期も一週間早めてほしいとのことです。私としては、一割は飲んで関係を強化したほうがいいと思うのですが。", "clip_id": "fb6ae93c7ad8eec2"}, {"speaker_role": "先輩", "text": "一割はさすがに厳しいよ。五％なら原価的に飲める。納期短縮は生産ラインに空きがあるから対応できそうだし、両方いけるんじゃないか。", "clip_id": "e130bff5be205da8"}, {"speaker_role": "後輩", "text": "では五％の値引きと納期一週間短縮、両方を提案書に盛り込みますか。", "clip_id": "3acce30aadb219b9"}, {"speaker_role": "先輩", "text": "いや、待って。さっき空きがあると言ったけど、来月分の受注が入ったから、納期短縮まではもう無理だ。値引きを五％にするなら、納期は今まで通りでいこう。", "clip_id": "ae90aaf7526953db"}, {"speaker_role": "後輩", "text": "承知しました。値引き五％、納期は従来どおりという形で先方にお伝えします。", "clip_id": "5260cabbcdc46067"}]', '0fa4140a0b6ae8a0', 1.0) on conflict (id) do update set bundle_id = excluded.bundle_id, item_type = excluded.item_type, level = excluded.level, seed_cell_id = excluded.seed_cell_id, setting = excluded.setting, relation = excluded.relation, function = excluded.function, channel = excluded.channel, scene_id = excluded.scene_id, speaker_role = excluded.speaker_role, listener_role = excluded.listener_role, topic = excluded.topic, stem = excluded.stem, correct_index = excluded.correct_index, explanation_ja = excluded.explanation_ja, explanation_en = excluded.explanation_en, vocab_notes = excluded.vocab_notes, documents = excluded.documents, dialogue = excluded.dialogue, narration_clip_id = excluded.narration_clip_id, model_p_correct = excluded.model_p_correct;
